test("does not expose provider response bodies or raw transport exceptions", async () => {
  for (const [status, message] of [
    [401, /could not authenticate/],
    [403, /could not authenticate/],
    [429, /rate limited/],
    [500, /temporarily unavailable/],
  ] as const) {
